# -*- coding: utf-8 -*-
"""The library: stories 5–50, written as briefs and expanded.

The four flagship stories in stories_data.py are hand-built end to end, with
bespoke diagrams composed for them alone. That does not scale to fifty, and
faking it by recycling artwork is the failure this project has corrected
twice already.

So these are content-first. Each brief carries every word, number, label and
diagram dataset that is unique to its story; the six beats from STYLE.md —
Wrong Picture, Crack, Turn, Machinery, Cost, Long View — are assembled by
`expand()` in a fixed order, because that order is the house grammar and is
not supposed to vary.

They are shorter than the flagship four and say so. What they are not is
padded: every one has a real reversal, real numbers, and a paper behind it.

    b(...)  one brief
    expand()  -> (story dict, paper dict)
"""


def b(slug, kicker, title, teaser, take, tone, scene, var, stand,
      wrong, d1, crack, turn, d2, cost, zoom, paper):
    return dict(slug=slug, kicker=kicker, title=title, teaser=teaser, take=take,
                tone=tone, scene=scene, var=var, stand=stand, wrong=wrong, d1=d1,
                crack=crack, turn=turn, d2=d2, cost=cost, zoom=zoom, paper=paper)


def pp(sub, abstract, findings, contested, unknowns, method, reading):
    return dict(sub=sub, abstract=abstract, findings=findings, contested=contested,
                unknowns=unknowns, method=method, reading=reading)


TONES = ['dusk', 'ember', 'deepsea', 'nebula', 'forest', 'solar', 'rose', 'void']


def expand(br, i):
    """One brief -> (story, paper), in the house order."""
    tone = br['tone']
    alt = TONES[(TONES.index(tone) + 3) % len(TONES)]

    # The full-bleed panel sits early, holding the teaser over the artwork as a
    # pull-quote. It used to sit just before the Turn and repeat the story's own
    # title and teaser, which put the title on the page twice and stacked two
    # big statements back to back. Here it sets up the Crack instead.
    blocks = [
        {'type': 'text', 'h': br['wrong'][0], 'p': list(br['wrong'][1:])},
        {'type': 'scene', 'tone': 'void', 'scene': br['scene'], 'var': br['var'] + 7,
         'h': br['teaser']},
        {'type': 'diagram', 'spec': br['d1'][0], 'caption': br['d1'][1]},
        {'type': 'text', 'h': br['crack'][0], 'p': list(br['crack'][1:])},
        {'type': 'turn', 'tone': alt, 'text': br['turn']},
        {'type': 'diagram', 'spec': br['d2'][0], 'caption': br['d2'][1]},
        {'type': 'text', 'h': br['cost'][0], 'p': list(br['cost'][1:])},
    ]

    story = {
        'slug': br['slug'], 'kicker': br['kicker'],
        'card_tone': tone, 'thumb': None, 'featured': False,
        'title': br['title'], 'teaser': br['teaser'], 'takeaway': br['take'],
        'hero': {'tone': tone, 'scene': br['scene'], 'var': br['var'],
                 'standfirst': br['stand']},
        'blocks': blocks,
        'zoomout': {'tone': tone, 'text': br['zoom']},
    }

    p = br['paper']
    paper = {
        'slug': br['slug'], 'title': br['title'].rstrip('?') + ': the research',
        'subtitle': p['sub'], 'date': 'August 2026',
        'minutes': max(4, 3 + len(p['findings'])),
        'abstract': p['abstract'],
        'sections': [{'h': 'What we looked at', 'p': [p['abstract']]}],
        'findings': p['findings'], 'contested': p['contested'],
        'unknowns': p['unknowns'], 'method': p['method'], 'reading': p['reading'],
    }
    return story, paper


